// Package clidoc renders the command line reference (docs/reference/cli) from the cobra command trees of the
// binaries. It is the only package that imports github.com/spf13/cobra/doc, and only test files import clidoc, so
// the documentation dependencies (cobra/doc, go-md2man, blackfriday) never become part of a released binary.
//
// The files are generated by "make docs-gen" (CLIDOC_UPDATE=1 go test -run TestCLIReference ./cmd/myriarchd) and
// guarded against drift by the same test without the variable (internal/docgen writes and compares the files).
package clidoc

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/spf13/cobra"
	"github.com/spf13/cobra/doc"

	"github.com/myriarch/myriarch/internal/brand"
)

// IndexFile is the name of the generated section index.
const IndexFile = "_index.md"

// indexWeight is the weight of the generated section index (reference section: gitops-schema 10, cli 20).
const indexWeight = 20

// FileName returns the file name of the page of a command: the command path with spaces replaced by "_".
func FileName(cmd *cobra.Command) string {
	return strings.ReplaceAll(cmd.CommandPath(), " ", "_") + ".md"
}

// Render returns the generated pages by file name: one page per available command of every root (depth-first, the
// subcommands in the order cobra lists them) and the section index _index.md. The result is deterministic.
// Render sets DisableAutoGenTag on every command of the trees.
func Render(roots ...*cobra.Command) (map[string][]byte, error) {
	files := make(map[string][]byte)
	var order []*cobra.Command
	var walk func(c *cobra.Command)
	walk = func(c *cobra.Command) {
		c.DisableAutoGenTag = true
		for _, sub := range c.Commands() {
			walk(sub)
		}
	}
	var collect func(c *cobra.Command)
	collect = func(c *cobra.Command) {
		if !c.IsAvailableCommand() || c.IsAdditionalHelpTopicCommand() {
			return
		}
		order = append(order, c)
		for _, sub := range c.Commands() {
			collect(sub)
		}
	}
	for _, r := range roots {
		walk(r)
		collect(r)
	}
	for i, c := range order {
		name := FileName(c)
		if _, dup := files[name]; dup {
			return nil, fmt.Errorf("clidoc: two commands produce the file %s", name)
		}
		page, err := renderPage(c, 10*(i+1))
		if err != nil {
			return nil, fmt.Errorf("clidoc: %s: %w", c.CommandPath(), err)
		}
		files[name] = page
	}
	files[IndexFile] = renderIndex(roots)
	return files, nil
}

// renderPage renders the page of one command with its front matter.
func renderPage(c *cobra.Command, weight int) ([]byte, error) {
	// The synopsis is plain text for terminals; angle brackets such as <file> would be taken for HTML tags in Markdown.
	short, long := c.Short, c.Long
	c.Short, c.Long = escapeAngle(short), escapeAngle(long)
	defer func() { c.Short, c.Long = short, long }()

	var body bytes.Buffer
	if err := doc.GenMarkdownCustom(c, &body, func(s string) string { return s }); err != nil {
		return nil, err
	}
	var out bytes.Buffer
	writeFrontMatter(&out, c.CommandPath(), weight, sentence(short))
	out.WriteString(strings.TrimRight(lintClean(body.String()), "\n"))
	out.WriteString("\n")
	return out.Bytes(), nil
}

// lintClean post-processes the Markdown that cobra writes so that it passes markdownlint (the website gate lints it): code
// fences get the language "text" (MD040), the SEE ALSO bullets use "-" instead of "*" (MD004) and a tab outside a code block
// becomes a space (MD010; cobra separates a link from its description with a tab).
func lintClean(md string) string {
	lines := strings.Split(md, "\n")
	inFence := false
	for i, line := range lines {
		if strings.HasPrefix(line, "```") {
			if !inFence && strings.TrimSpace(line) == "```" {
				lines[i] = "```text"
			}
			inFence = !inFence
			continue
		}
		if inFence {
			continue
		}
		if strings.HasPrefix(line, "* ") {
			line = "- " + line[2:]
		}
		lines[i] = strings.ReplaceAll(strings.ReplaceAll(line, "\t - ", " - "), "\t", " ")
	}
	return strings.Join(lines, "\n")
}

func renderIndex(roots []*cobra.Command) []byte {
	var b bytes.Buffer
	writeFrontMatter(&b, "CLI reference", indexWeight,
		"Reference of every command and option of the myriarch binaries, generated from the command line definitions.")
	b.WriteString("This directory is generated from the command line definitions of the binaries by `make docs-gen`. " +
		"Do not edit the files by hand: `make docs-check` fails when they differ from the code.\n\n")
	b.WriteString("| Command | Description |\n|---|---|\n")
	for _, r := range roots {
		if !r.IsAvailableCommand() {
			continue
		}
		fmt.Fprintf(&b, "| [%s](%s) | %s |\n", r.CommandPath(), FileName(r), cell(r.Short))
	}
	fmt.Fprintf(&b, "\nThe short name `%[1]s` is an optional alias of `%[2]s`. It is not installed and not shipped as a second binary: "+
		"create it yourself, for example with `alias %[1]s=%[2]s` in a POSIX shell or `Set-Alias %[1]s %[2]s` in PowerShell. "+
		"Everything documented for `%[2]s` applies to `%[1]s`.\n", brand.CLIAlias, brand.CLIBinary)
	return b.Bytes()
}

// writeFrontMatter writes the Hugo front matter block (keys in the fixed order title, weight, description).
func writeFrontMatter(b *bytes.Buffer, title string, weight int, description string) {
	fmt.Fprintf(b, "---\ntitle: %s\nweight: %d\ndescription: %s\n---\n\n", quote(title), weight, quote(description))
}

// quote returns s as a double-quoted YAML (JSON) string without HTML escaping.
func quote(s string) string {
	var b bytes.Buffer
	enc := json.NewEncoder(&b)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(s); err != nil {
		panic(err) // a string always encodes
	}
	return strings.TrimRight(b.String(), "\n")
}

// sentence returns s as one sentence that ends with a period.
func sentence(s string) string {
	s = strings.TrimSpace(s)
	if s == "" || strings.HasSuffix(s, ".") {
		return s
	}
	return s + "."
}

func escapeAngle(s string) string { return strings.ReplaceAll(s, "<", "&lt;") }

// cell makes s fit into a Markdown table cell.
func cell(s string) string {
	return strings.ReplaceAll(escapeAngle(strings.Join(strings.Fields(s), " ")), "|", "\\|")
}
